#[local] Instance boottomain_fx : OSSVerify.Proofs.libpcap.fuzz_pcap.lib.Common.PropExec__Common.PropExec.FPState := OSSVerify.Proofs.libpcap.fuzz_pcap.lib.Common.PropExec__Common.PropExec.fx0.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.


Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Section Compose.
  Variables (sp brk mbase : word) (draw : EntryDraw) (lim : Z) (inp : ProcInput).
  Hypothesis VI : valid_input inp.
  Hypothesis VE : valid_entry IMG (mkEntry sp brk mbase draw) inp.

  #[using="VI VE"] Theorem boot_to_main : forall (pl : placements) (K : TSet), 2 ^ 25 <= lim ->
    (forall (a tid c p8 sb p10 p12 p15 p24 : word) (W lb : Z) (js : list word) R M mdl, length js = 92%nat ->
       BootS11w1.at_main sp brk mbase draw lim inp a tid c pl p8 sb p10 p12 p15 p24 W lb js R M mdl ->
       srealizes SEGS (mkCfg (mkst R (Z_to_bv 64 A_main) M ROM) mdl) K) ->
    (forall (a tid c p8 sb p10 p12 p15 p24 : word) (W lb : Z) (js : list word) R M mdl, length js = 92%nat ->
       BootS11w2.at_main sp brk mbase draw lim inp a tid c pl p8 sb p10 p12 p15 p24 W lb js R M mdl ->
       srealizes SEGS (mkCfg (mkst R (Z_to_bv 64 A_main) M ROM) mdl) K) ->
    srealizes SEGS (init_config SEGS PC0 PH sp brk mbase draw lim inp) K.
  Proof.
    intros pl K Hlim HK1 HK2.
    apply (boot_to_T0 sp brk mbase draw lim inp VI VE pl K Hlim). intros a tid c p8 sb p10 p12 p15 W lb js R M mdl Hjs HT.
    destruct (Z_le_gt_dec (STv sp) (bv_unsigned sp - 96)) as [HW|HW].
    - apply (BootS11w1.boot_s11 sp brk mbase draw lim inp VI VE a tid c pl p8 sb p10 p12 p15 W lb js R M mdl K Hlim Hjs HW HT).
      intros p24 ks R' M' mdl' Hks HM. apply (HK1 a tid c p8 sb p10 p12 p15 p24 W lb (js ++ ks) R' M' mdl'); [rewrite length_app, Hjs, Hks; reflexivity | exact HM].
    - assert (HW2 : BootS11w2.WORLD_OK sp) by (unfold BootS11w2.WORLD_OK; lia).
      apply (BootS11w2.boot_s11 sp brk mbase draw lim inp VI VE a tid c pl p8 sb p10 p12 p15 W lb js R M mdl K Hlim Hjs HW2 HT).
      intros p24 ks R' M' mdl' Hks HM. apply (HK2 a tid c p8 sb p10 p12 p15 p24 W lb (js ++ ks) R' M' mdl'); [rewrite length_app, Hjs, Hks; reflexivity | exact HM].
  Qed.
End Compose.

